def pass_plan_summary(plan_name):
    plan = PASS_PLAN_PRESETS.get(str(plan_name or "").strip())
    if not plan:
        return ""
    setting = get_pass_product_setting(plan_name)
    price_text = format_pass_price(setting.get("price", 0))
    sale_text = "" if setting.get("active", True) else " · 현재 판매중지"
    return (
        f"{plan_name} · {plan['display']} · 유효기간 {plan['valid_days']}일 · "
        f"{price_text}{sale_text}"
    )


def apply_pass_plan_pending(code, plan_name):
    """상품 초안을 고객에게 미결제 상태로 적용합니다. 결제완료 처리는 관리자가 별도로 확인합니다."""
    plan = PASS_PLAN_PRESETS.get(str(plan_name or "").strip())
    if not plan:
        raise ValueError("선택한 이용권 상품을 찾지 못했습니다.")
    setting = get_pass_product_setting(plan_name)
    if not setting.get("active", True):
        raise ValueError("현재 판매하지 않는 이용권입니다.")
    expires_at = (_customer_now() + timedelta(days=int(plan["valid_days"]))).date().isoformat()
    return update_customer_pass(
        code=code,
        pass_name=plan_name,
        payment_status="미결제",
        remaining=int(plan["questions"]),
        expires_at=expires_at,
    )


def request_pass_plan_for_customer(profile, plan_name):
    """고객이 이용권 상품을 신청합니다. 결제는 아직 발생하지 않으며 미결제 상태로만 저장합니다."""
    if not profile or not profile.get("code"):
        return False, (
            "이용권 신청은 고객 코드가 있는 등록 고객부터 사용할 수 있습니다. "
            "왼쪽 '고객 구분'에서 기존 고객을 확인하거나 새 고객을 등록해 주세요."
        ), None

    latest = get_customer(profile.get("code")) or profile
    current_pass = customer_pass_state(latest)

    if current_pass.get("active"):
        return False, (
            f"현재 '{current_pass.get('name', '이용권')}'을 사용 중입니다. "
            "기존 이용권을 모두 사용한 뒤 새 이용권을 신청하거나 관리자에게 변경을 요청해 주세요."
        ), latest

    if current_pass.get("payment_status") == "입금확인중":
        return False, (
            f"현재 '{current_pass.get('name', '이용권')}' 결제를 확인 중입니다. "
            "확인이 끝난 뒤 변경해 주세요."
        ), latest

    updated = apply_pass_plan_pending(profile.get("code"), plan_name)
    setting = get_pass_product_setting(plan_name)
    order = create_payment_order(
        customer_code=profile.get("code"),
        plan_name=plan_name,
        amount=int(setting.get("price", 0) or 0),
    )
    return True, (
        f"'{plan_name}' 신청이 저장되었습니다. {format_pass_price(setting.get('price', 0))}. "
        f"주문번호 {order.get('order_id', '-')}. "
        "아직 결제된 것은 아닙니다. 결제 후 '입금했습니다'를 눌러 주세요."
    ), updated


def _customer_now():
    """고객 방문 집계는 한국 시간(KST)을 기준으로 합니다."""
    return datetime.now(CUSTOMER_KST)


def _customer_now_text():
    return _customer_now().strftime("%Y-%m-%d %H:%M:%S")


def _customer_connect():
    conn = sqlite3.connect(CUSTOMER_DB_PATH, timeout=10)
    conn.row_factory = sqlite3.Row
    return conn


def init_customer_db():
    """기존 고객 DB를 유지하면서 이용권 운영에 필요한 최소 컬럼을 자동 확장합니다."""
    with _customer_connect() as conn:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS customers (
                code TEXT PRIMARY KEY,
                nickname TEXT NOT NULL,
                created_at TEXT NOT NULL,
                last_visit_at TEXT NOT NULL,
                visit_count INTEGER NOT NULL DEFAULT 1,
                ai_question_total INTEGER NOT NULL DEFAULT 0,
                last_category TEXT NOT NULL DEFAULT '',
                pass_name TEXT NOT NULL DEFAULT '',
                payment_status TEXT NOT NULL DEFAULT '미결제',
                pass_remaining INTEGER NOT NULL DEFAULT 0,
                pass_expires_at TEXT NOT NULL DEFAULT '',
                pass_updated_at TEXT NOT NULL DEFAULT ''
            )
            """
        )

        existing_columns = {
            str(row["name"])
            for row in conn.execute("PRAGMA table_info(customers)").fetchall()
        }
        migrations = {
            "pass_name": "TEXT NOT NULL DEFAULT ''",
            "payment_status": "TEXT NOT NULL DEFAULT '미결제'",
            "pass_remaining": "INTEGER NOT NULL DEFAULT 0",
            "pass_expires_at": "TEXT NOT NULL DEFAULT ''",
            "pass_updated_at": "TEXT NOT NULL DEFAULT ''",
        }
        for column_name, column_sql in migrations.items():
            if column_name not in existing_columns:
                conn.execute(
                    f"ALTER TABLE customers ADD COLUMN {column_name} {column_sql}"
                )

        # v2.0.0: 제휴/추천 링크는 고객 개인정보와 분리된 별도 표로 관리합니다.
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS affiliate_links (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                category TEXT NOT NULL DEFAULT '전체·공통',
                link_type TEXT NOT NULL DEFAULT '일반 추천',
                title TEXT NOT NULL,
                description TEXT NOT NULL DEFAULT '',
                url TEXT NOT NULL,
                active INTEGER NOT NULL DEFAULT 1,
                click_count INTEGER NOT NULL DEFAULT 0,
                last_clicked_at TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL
            )
            """
        )

        affiliate_columns = {
            str(row["name"])
            for row in conn.execute("PRAGMA table_info(affiliate_links)").fetchall()
        }
        if "link_type" not in affiliate_columns:
            # 기존 v2.0.0 링크는 일반 추천으로 유지합니다.
            conn.execute(
                "ALTER TABLE affiliate_links ADD COLUMN link_type TEXT NOT NULL DEFAULT '일반 추천'"
            )
        if "click_count" not in affiliate_columns:
            conn.execute(
                "ALTER TABLE affiliate_links ADD COLUMN click_count INTEGER NOT NULL DEFAULT 0"
            )
        if "last_clicked_at" not in affiliate_columns:
            conn.execute(
                "ALTER TABLE affiliate_links ADD COLUMN last_clicked_at TEXT NOT NULL DEFAULT ''"
            )

        # v2.2.0: 이용권 상품 가격/판매여부와 고객용 결제 안내를 별도 설정으로 저장합니다.
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS pass_products (
                plan_name TEXT PRIMARY KEY,
                price INTEGER NOT NULL DEFAULT 0,
                active INTEGER NOT NULL DEFAULT 1,
                updated_at TEXT NOT NULL DEFAULT ''
            )
            """
        )
        for _plan_name, _plan_info in PASS_PLAN_PRESETS.items():
            conn.execute(
                """
                INSERT OR IGNORE INTO pass_products
                (plan_name, price, active, updated_at)
                VALUES (?, ?, 1, '')
                """,
                (_plan_name, int(_plan_info.get("default_price", 0) or 0)),
            )

        # v3.3.3 출시 가격 정정:
        # 직전 운영값과 정확히 일치할 때만 새 가격으로 자동 보정합니다.
        # 관리자가 별도 가격으로 수정한 값은 덮어쓰지 않습니다.
        conn.execute(
            """
            UPDATE pass_products
            SET price = 9900
            WHERE plan_name = '라이트 5회권' AND price IN (5000, 25000)
            """
        )
        conn.execute(
            """
            UPDATE pass_products
            SET price = 17900
            WHERE plan_name = '기본 10회권' AND price = 45000
            """
        )
        conn.execute(
            """
            UPDATE pass_products
            SET price = 39900
            WHERE plan_name = '단골 30회권' AND price = 120000
            """
        )

        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS service_settings (
                setting_key TEXT PRIMARY KEY,
                setting_value TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            )
            """
        )
        conn.execute(
            """
            INSERT OR IGNORE INTO service_settings
            (setting_key, setting_value, updated_at)
            VALUES ('payment_guide', '결제 방법은 운영자에게 문의해 주세요.', '')
            """
        )

        # v3.1.0: 고객 감사 이벤트 기본 설정
        for _event_key, _event_value in EVENT_DEFAULTS.items():
            conn.execute(
                """
                INSERT OR IGNORE INTO service_settings
                (setting_key, setting_value, updated_at)
                VALUES (?, ?, '')
                """,
                (_event_key, _event_value),
            )

        # v2.4.0: 실제 PG 연동 전에 주문번호/금액/상태를 별도 기록합니다.
        # 카드번호, 계좌 비밀번호 등 결제수단 민감정보는 저장하지 않습니다.
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS payment_orders (
                order_id TEXT PRIMARY KEY,
                customer_code TEXT NOT NULL,
                plan_name TEXT NOT NULL,
                amount INTEGER NOT NULL DEFAULT 0,
                payment_method TEXT NOT NULL DEFAULT '수동 입금',
                status TEXT NOT NULL DEFAULT '미결제',
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                paid_at TEXT NOT NULL DEFAULT ''
            )
            """
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_payment_orders_customer ON payment_orders(customer_code, created_at)"
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_payment_orders_status ON payment_orders(status, updated_at)"
        )

        # v2.7.0: 상담 방문 리워드 보관함
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS talisman_rewards (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                customer_code TEXT NOT NULL,
                milestone INTEGER NOT NULL,
                talisman_type TEXT NOT NULL,
                title TEXT NOT NULL,
                message TEXT NOT NULL,
                created_at TEXT NOT NULL,
                UNIQUE(customer_code, milestone)
            )
            """
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_talisman_customer ON talisman_rewards(customer_code, milestone)"
        )

        # v2.8.0: 웰컴 여정의 최소 활동 상태
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS customer_journey (
                customer_code TEXT PRIMARY KEY,
                saju_done INTEGER NOT NULL DEFAULT 0,
                tarot_done INTEGER NOT NULL DEFAULT 0,
                ai_done INTEGER NOT NULL DEFAULT 0,
                updated_at TEXT NOT NULL DEFAULT ''
            )
            """
        )

        # v3.1.0: KST 기준 실제 방문 일자를 별도로 보관합니다.
        # 기존 누적 방문 횟수는 유지하고, 업데이트 이후부터 날짜별 방문을 정확히 쌓습니다.
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS customer_visit_history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                customer_code TEXT NOT NULL,
                visit_date TEXT NOT NULL,
                visited_at TEXT NOT NULL,
                UNIQUE(customer_code, visit_date)
            )
            """
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_visit_history_date ON customer_visit_history(visit_date, customer_code)"
        )

        # 기존 고객은 과거 방문 날짜 전체를 복원할 수 없으므로 최근 방문일 1건만 안전하게 이관합니다.
        conn.execute(
            """
            INSERT OR IGNORE INTO customer_visit_history
            (customer_code, visit_date, visited_at)
            SELECT code, substr(last_visit_at, 1, 10), last_visit_at
            FROM customers
            WHERE trim(last_visit_at) <> ''
              AND length(last_visit_at) >= 10
            """
        )

        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS event_draws (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                event_key TEXT NOT NULL UNIQUE,
                event_name TEXT NOT NULL,
                prize_text TEXT NOT NULL DEFAULT '',
                eligibility_rule TEXT NOT NULL DEFAULT '',
                candidate_count INTEGER NOT NULL DEFAULT 0,
                winner_count INTEGER NOT NULL DEFAULT 0,
                drawn_at TEXT NOT NULL,
                created_at TEXT NOT NULL
            )
            """
        )
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS event_winners (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                draw_id INTEGER NOT NULL,
                customer_code TEXT NOT NULL,
                winner_order INTEGER NOT NULL DEFAULT 1,
                created_at TEXT NOT NULL,
                UNIQUE(draw_id, customer_code)
            )
            """
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_event_winners_customer ON event_winners(customer_code, created_at)"
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_event_winners_draw ON event_winners(draw_id, winner_order)"
        )

        # v3.2.0: 희망 이야기는 텍스트만 저장하고 사진/연락처는 기본 수집하지 않습니다.
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS hope_stories (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                customer_code TEXT NOT NULL,
                category TEXT NOT NULL,
                title TEXT NOT NULL,
                story TEXT NOT NULL,
                action_text TEXT NOT NULL DEFAULT '',
                anonymous INTEGER NOT NULL DEFAULT 1,
                status TEXT NOT NULL DEFAULT '검토중',
                reward_label TEXT NOT NULL DEFAULT '',
                admin_note TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL,
                reviewed_at TEXT NOT NULL DEFAULT '',
                approved_at TEXT NOT NULL DEFAULT ''
            )
            """
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_hope_stories_status ON hope_stories(status, id)"
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_hope_stories_customer ON hope_stories(customer_code, id)"
        )

        conn.commit()


def _row_to_customer(row):
    return dict(row) if row is not None else None


def get_customer(code):
    code = str(code or "").strip().upper()
    if not code:
        return None
    init_customer_db()
    with _customer_connect() as conn:
        row = conn.execute("SELECT * FROM customers WHERE code = ?", (code,)).fetchone()
    return _row_to_customer(row)


def format_pass_price(price):
    try:
        amount = max(0, int(price or 0))
    except (TypeError, ValueError):
        amount = 0
    return f"{amount:,}원" if amount > 0 else "가격 문의"


def get_pass_product_setting(plan_name):
    plan_name = str(plan_name or "").strip()
    init_customer_db()
    with _customer_connect() as conn:
        row = conn.execute(
            "SELECT plan_name, price, active, updated_at FROM pass_products WHERE plan_name = ?",
            (plan_name,),
        ).fetchone()
    if row is None:
        return {"plan_name": plan_name, "price": 0, "active": True, "updated_at": ""}
    item = dict(row)
    item["price"] = int(item.get("price", 0) or 0)
    item["active"] = bool(int(item.get("active", 1) or 0))
    return item


def get_all_pass_product_settings():
    return {name: get_pass_product_setting(name) for name in PASS_PLAN_PRESETS}


def save_pass_product_setting(plan_name, price, active=True):
    plan_name = str(plan_name or "").strip()
    if plan_name not in PASS_PLAN_PRESETS:
        raise ValueError("지원하지 않는 이용권 상품입니다.")
    price = max(0, min(int(price or 0), 100_000_000))
    now = _customer_now_text()
    init_customer_db()
    with _customer_connect() as conn:
        conn.execute(
            """
            INSERT INTO pass_products (plan_name, price, active, updated_at)
            VALUES (?, ?, ?, ?)
            ON CONFLICT(plan_name) DO UPDATE SET
                price = excluded.price,
                active = excluded.active,
                updated_at = excluded.updated_at
            """,
            (plan_name, price, 1 if active else 0, now),
        )
        conn.commit()
    return get_pass_product_setting(plan_name)


def get_service_setting(setting_key, default=""):
    setting_key = str(setting_key or "").strip()
    if not setting_key:
        return str(default or "")
    init_customer_db()
    with _customer_connect() as conn:
        row = conn.execute(
            "SELECT setting_value FROM service_settings WHERE setting_key = ?",
            (setting_key,),
        ).fetchone()
    if row is None:
        return str(default or "")
    return str(row["setting_value"] or "")


def save_service_setting(setting_key, setting_value):
    setting_key = str(setting_key or "").strip()
    if not setting_key:
        raise ValueError("설정 키가 없습니다.")
    value = str(setting_value or "").strip()[:2000]
    now = _customer_now_text()
    init_customer_db()
    with _customer_connect() as conn:
        conn.execute(
            """
            INSERT INTO service_settings (setting_key, setting_value, updated_at)
            VALUES (?, ?, ?)
            ON CONFLICT(setting_key) DO UPDATE SET
                setting_value = excluded.setting_value,
                updated_at = excluded.updated_at
            """,
            (setting_key, value, now),
        )
        conn.commit()
    return value


def get_payment_guide():
    init_customer_db()
    with _customer_connect() as conn:
        row = conn.execute(
            "SELECT setting_value FROM service_settings WHERE setting_key = 'payment_guide'"
        ).fetchone()
    guide = str(row["setting_value"] if row else "").strip()
    return guide or "결제 방법은 운영자에게 문의해 주세요."


def save_payment_guide(guide):
    guide = str(guide or "").strip()[:1000]
    if not guide:
        guide = "결제 방법은 운영자에게 문의해 주세요."
    now = _customer_now_text()
    init_customer_db()
    with _customer_connect() as conn:
        conn.execute(
            """
            INSERT INTO service_settings (setting_key, setting_value, updated_at)
            VALUES ('payment_guide', ?, ?)
            ON CONFLICT(setting_key) DO UPDATE SET
                setting_value = excluded.setting_value,
                updated_at = excluded.updated_at
            """,
            (guide, now),
        )
        conn.commit()
    return guide


def mark_customer_payment_sent(profile):
    """고객이 입금했다고 표시합니다. 실제 결제 검증은 하지 않고 관리자 확인 대기 상태로만 바꿉니다."""
    if not profile or not profile.get("code"):
        return False, "먼저 등록 고객으로 확인해 주세요.", profile

    latest = get_customer(profile.get("code")) or profile
    current = customer_pass_state(latest)
    if current.get("active"):
        return False, "이미 활성 이용권을 사용 중입니다.", latest
    if current.get("payment_status") == "입금확인중":
        return False, "이미 입금확인중으로 접수되어 있습니다.", latest
    if current.get("payment_status") != "미결제" or current.get("remaining", 0) <= 0:
        return False, "먼저 이용권을 신청해 주세요.", latest

    updated = update_customer_pass(
        code=latest.get("code"),
        pass_name=current.get("name", ""),
        payment_status="입금확인중",
        remaining=current.get("remaining", 0),
        expires_at=current.get("expires_at", ""),
    )
    update_latest_payment_order_status(latest.get("code"), "입금확인중")
    return True, "입금확인중으로 접수했습니다. 관리자가 확인하면 이용권이 활성화됩니다.", updated


def pending_pass_requests(limit=50):
    """관리자용 결제대기 목록. 결제수단 정보는 저장하거나 반환하지 않습니다."""
    init_customer_db()
    safe_limit = max(1, min(int(limit or 50), 200))
    with _customer_connect() as conn:
        rows = conn.execute(
            """
            SELECT code, nickname, pass_name, payment_status,
                   pass_remaining, pass_expires_at, pass_updated_at
            FROM customers
            WHERE pass_remaining > 0
              AND payment_status IN ('미결제', '입금확인중')
            ORDER BY
                CASE WHEN payment_status = '입금확인중' THEN 0 ELSE 1 END,
                pass_updated_at DESC,
                code DESC
            LIMIT ?
            """,
            (safe_limit,),
        ).fetchall()
    return [dict(row) for row in rows]


def _new_payment_order_id():
    stamp = _customer_now().strftime("%Y%m%d-%H%M%S")
    token = secrets.token_hex(2).upper()
    return f"PAY-{stamp}-{token}"


def create_payment_order(customer_code, plan_name, amount=0):
    """새 이용권 신청을 결제 주문으로 기록합니다. 민감한 결제수단 정보는 저장하지 않습니다."""
    customer_code = str(customer_code or "").strip().upper()
    plan_name = str(plan_name or "").strip()
    amount = max(0, int(amount or 0))
    if not customer_code:
        raise ValueError("고객 코드가 없습니다.")
    if not plan_name:
        raise ValueError("이용권 이름이 없습니다.")

    init_customer_db()
    now = _customer_now_text()
    order_id = _new_payment_order_id()

    with _customer_connect() as conn:
        # 같은 고객의 이전 미결제 주문은 새 신청으로 교체되었다는 뜻으로 취소 처리합니다.
        conn.execute(
            """
            UPDATE payment_orders
            SET status = '취소', updated_at = ?
            WHERE customer_code = ? AND status = '미결제'
            """,
            (now, customer_code),
        )
        conn.execute(
            """
            INSERT INTO payment_orders
            (order_id, customer_code, plan_name, amount, payment_method, status,
             created_at, updated_at, paid_at)
            VALUES (?, ?, ?, ?, '수동 입금', '미결제', ?, ?, '')
            """,
            (order_id, customer_code, plan_name, amount, now, now),
        )
        conn.commit()
        row = conn.execute(
            "SELECT * FROM payment_orders WHERE order_id = ?",
            (order_id,),
        ).fetchone()
    return dict(row)


def get_latest_payment_order(customer_code, include_closed=True):
    customer_code = str(customer_code or "").strip().upper()
    if not customer_code:
        return None
    init_customer_db()
    sql = """
        SELECT * FROM payment_orders
        WHERE customer_code = ?
    """
    params = [customer_code]
    if not include_closed:
        sql += " AND status IN ('미결제', '입금확인중')"
    sql += " ORDER BY created_at DESC, order_id DESC LIMIT 1"
    with _customer_connect() as conn:
        row = conn.execute(sql, params).fetchone()
    return dict(row) if row else None


def update_latest_payment_order_status(customer_code, status):
    customer_code = str(customer_code or "").strip().upper()
    status = str(status or "").strip()
    allowed = {"미결제", "입금확인중", "결제완료", "취소", "환불"}
    if status not in allowed:
        raise ValueError("지원하지 않는 주문 상태입니다.")
    if not customer_code:
        return None

    init_customer_db()
    now = _customer_now_text()
    with _customer_connect() as conn:
        row = conn.execute(
            """
            SELECT order_id FROM payment_orders
            WHERE customer_code = ?
              AND status IN ('미결제', '입금확인중')
            ORDER BY created_at DESC, order_id DESC
            LIMIT 1
            """,
            (customer_code,),
        ).fetchone()
        if not row:
            return None
        paid_at = now if status == "결제완료" else ""
        conn.execute(
            """
            UPDATE payment_orders
            SET status = ?, updated_at = ?, paid_at = ?
            WHERE order_id = ?
            """,
            (status, now, paid_at, row["order_id"]),
        )
        conn.commit()
        updated = conn.execute(
            "SELECT * FROM payment_orders WHERE order_id = ?",
            (row["order_id"],),
        ).fetchone()
    return dict(updated) if updated else None


