def reconcile_open_payment_orders():
    """열린 주문 상태를 고객 이용권 상태와 맞춥니다.

    고객 화면에서 '입금확인중'으로 바뀌었는데 관리자 목록에서 사라지는
    상태 불일치를 방지합니다. 결제완료/취소 주문은 건드리지 않습니다.
    """
    init_customer_db()
    with _customer_connect() as conn:
        rows = conn.execute(
            """
            SELECT o.customer_code, o.plan_name, o.status
            FROM payment_orders o
            INNER JOIN (
                SELECT customer_code, MAX(created_at || '|' || order_id) AS latest_key
                FROM payment_orders
                WHERE status IN ('미결제', '입금확인중')
                GROUP BY customer_code
            ) latest
              ON latest.customer_code = o.customer_code
             AND (o.created_at || '|' || o.order_id) = latest.latest_key
            WHERE o.status IN ('미결제', '입금확인중')
            """
        ).fetchall()

        for row in rows:
            code = str(row["customer_code"] or "").strip().upper()
            if not code:
                continue
            customer = conn.execute(
                """
                SELECT code, pass_name, payment_status, pass_remaining
                FROM customers
                WHERE code = ?
                """,
                (code,),
            ).fetchone()
            if not customer:
                continue

            order_status = str(row["status"] or "").strip()
            order_plan = str(row["plan_name"] or "").strip()
            customer_status = str(customer["payment_status"] or "").strip()
            customer_plan = str(customer["pass_name"] or "").strip()

            if customer_status != order_status or (order_plan and customer_plan != order_plan):
                conn.execute(
                    """
                    UPDATE customers
                    SET payment_status = ?,
                        pass_name = CASE WHEN ? <> '' THEN ? ELSE pass_name END,
                        pass_updated_at = ?
                    WHERE code = ?
                    """,
                    (order_status, order_plan, order_plan, _customer_now_text(), code),
                )

        conn.commit()


def admin_pending_payment_requests(limit=100):
    """관리자 결제대기 목록을 주문 기록 중심으로 구성합니다.

    최신 미결제/입금확인중 주문을 우선 표시하고,
    주문번호가 없는 예전 고객 결제대기 데이터도 함께 보존합니다.
    """
    init_customer_db()
    safe_limit = max(1, min(int(limit or 100), 200))

    with _customer_connect() as conn:
        order_rows = conn.execute(
            """
            SELECT
                c.code AS code,
                c.nickname AS nickname,
                o.plan_name AS pass_name,
                o.status AS payment_status,
                c.pass_remaining AS pass_remaining,
                c.pass_expires_at AS pass_expires_at,
                o.updated_at AS pass_updated_at,
                o.order_id AS order_id,
                o.amount AS order_amount
            FROM payment_orders o
            LEFT JOIN customers c ON c.code = o.customer_code
            WHERE o.status IN ('미결제', '입금확인중')
              AND o.order_id = (
                  SELECT o2.order_id
                  FROM payment_orders o2
                  WHERE o2.customer_code = o.customer_code
                    AND o2.status IN ('미결제', '입금확인중')
                  ORDER BY o2.created_at DESC, o2.order_id DESC
                  LIMIT 1
              )
            ORDER BY
                CASE WHEN o.status = '입금확인중' THEN 0 ELSE 1 END,
                o.updated_at DESC,
                o.order_id DESC
            LIMIT ?
            """,
            (safe_limit,),
        ).fetchall()

        rows = [dict(row) for row in order_rows]
        seen_codes = {str(row.get("code", "") or "") for row in rows}

        legacy_rows = conn.execute(
            """
            SELECT code, nickname, pass_name, payment_status,
                   pass_remaining, pass_expires_at, pass_updated_at
            FROM customers
            WHERE pass_remaining > 0
              AND payment_status IN ('미결제', '입금확인중')
            ORDER BY
                CASE WHEN payment_status = '입금확인중' THEN 0 ELSE 1 END,
                pass_updated_at DESC,
                code DESC
            LIMIT ?
            """,
            (safe_limit,),
        ).fetchall()

        for row in legacy_rows:
            item = dict(row)
            code = str(item.get("code", "") or "")
            if code in seen_codes:
                continue
            item["order_id"] = ""
            item["order_amount"] = 0
            rows.append(item)

    rows.sort(
        key=lambda r: (
            0 if str(r.get("payment_status", "")) == "입금확인중" else 1,
            str(r.get("pass_updated_at", "")),
        )
    )
    return rows[:safe_limit]


def get_talisman_collection(customer_code):
    customer_code = str(customer_code or "").strip().upper()
    if not customer_code:
        return []
    init_customer_db()
    with _customer_connect() as conn:
        rows = conn.execute(
            """
            SELECT id, customer_code, milestone, talisman_type, title, message, created_at
            FROM talisman_rewards
            WHERE customer_code = ?
            ORDER BY milestone ASC, id ASC
            """,
            (customer_code,),
        ).fetchall()
    return [dict(row) for row in rows]


def talisman_reward_status(profile):
    """누적 상담 방문 5회마다 1개씩 받을 수 있는 리워드 상태를 계산합니다."""
    if not profile or not profile.get("code"):
        return {
            "visits": 0,
            "earned_slots": 0,
            "claimed": 0,
            "available": 0,
            "available_milestones": [],
            "next_milestone": TALISMAN_REWARD_STEP,
            "remaining_to_next": TALISMAN_REWARD_STEP,
            "collection": [],
            "owned_types": set(),
        }

    latest = get_customer(profile.get("code")) or profile
    visits = max(0, int(latest.get("visit_count", 0) or 0))
    collection = get_talisman_collection(latest.get("code"))
    claimed_milestones = {int(item.get("milestone", 0) or 0) for item in collection}
    earned_milestones = list(
        range(TALISMAN_REWARD_STEP, visits + 1, TALISMAN_REWARD_STEP)
    )
    available_milestones = [m for m in earned_milestones if m not in claimed_milestones]
    next_milestone = ((visits // TALISMAN_REWARD_STEP) + 1) * TALISMAN_REWARD_STEP

    return {
        "visits": visits,
        "earned_slots": len(earned_milestones),
        "claimed": len(collection),
        "available": len(available_milestones),
        "available_milestones": available_milestones,
        "next_milestone": next_milestone,
        "remaining_to_next": max(0, next_milestone - visits),
        "collection": collection,
        "owned_types": {
            str(item.get("talisman_type", ""))
            for item in collection
            if str(item.get("talisman_type", ""))
        },
    }


def claim_talisman_reward(profile, talisman_type):
    """달성한 다음 미수령 구간의 디지털 부적을 1개 지급합니다."""
    talisman_type = str(talisman_type or "").strip()
    if talisman_type not in TALISMAN_TYPES:
        raise ValueError("지원하지 않는 부적 종류입니다.")
    if not profile or not profile.get("code"):
        raise ValueError("등록 고객 확인이 필요합니다.")

    latest = get_customer(profile.get("code")) or profile
    status = talisman_reward_status(latest)
    if status.get("available", 0) <= 0:
        raise ValueError("현재 받을 수 있는 무료 부적이 없습니다.")

    owned_types = set(status.get("owned_types", set()))
    if len(owned_types) < len(TALISMAN_TYPES) and talisman_type in owned_types:
        raise ValueError("처음 4종을 모으는 동안에는 아직 없는 부적을 선택해 주세요.")

    milestone = min(status.get("available_milestones") or [])
    info = TALISMAN_TYPES[talisman_type]
    now = _customer_now_text()
    init_customer_db()
    with _customer_connect() as conn:
        conn.execute(
            """
            INSERT INTO talisman_rewards
            (customer_code, milestone, talisman_type, title, message, created_at)
            VALUES (?, ?, ?, ?, ?, ?)
            """,
            (
                str(latest.get("code", "")).strip().upper(),
                int(milestone),
                talisman_type,
                info["title"],
                info["message"],
                now,
            ),
        )
        conn.commit()
        row = conn.execute(
            """
            SELECT id, customer_code, milestone, talisman_type, title, message, created_at
            FROM talisman_rewards
            WHERE customer_code = ? AND milestone = ?
            """,
            (str(latest.get("code", "")).strip().upper(), int(milestone)),
        ).fetchone()
    return dict(row)


def _wrap_svg_text(value, max_chars=18):
    value = str(value or "").strip()
    if not value:
        return [""]
    if len(value) <= max_chars:
        return [value]
    return [value[i:i + max_chars] for i in range(0, len(value), max_chars)][:4]


