def _masked_customer_code(code):
    code = str(code or "")
    if len(code) <= 5:
        return code
    return f"{code[:5]}•••{code[-2:]}"


def growth_event_status():
    """등록 고객 수와 100/500/1000명 이벤트 진행 상태를 계산합니다."""
    init_customer_db()
    with _customer_connect() as conn:
        row = conn.execute("SELECT COUNT(*) AS cnt FROM customers").fetchone()
    total = int(row["cnt"] if row else 0)

    reached = 0
    next_milestone = None
    for milestone in GROWTH_EVENT_MILESTONES:
        if total >= milestone:
            reached = milestone
        elif next_milestone is None:
            next_milestone = milestone

    try:
        active = int(get_service_setting("active_growth_milestone", "0") or 0)
    except ValueError:
        active = 0
    if active not in GROWTH_EVENT_MILESTONES:
        active = 0

    remaining = max(0, (next_milestone or total) - total) if next_milestone else 0
    return {
        "total": total,
        "reached": reached,
        "next": next_milestone,
        "remaining": remaining,
        "active": active,
    }


def set_active_growth_event(milestone):
    milestone = int(milestone or 0)
    if milestone not in GROWTH_EVENT_MILESTONES:
        raise ValueError("지원하지 않는 고객 돌파 이벤트입니다.")
    status = growth_event_status()
    if status["total"] < milestone:
        raise ValueError(f"아직 등록 고객 {milestone}명에 도달하지 않았습니다.")
    save_service_setting("active_growth_milestone", str(milestone))
    return growth_event_status()


def close_growth_event():
    save_service_setting("active_growth_milestone", "0")


def get_active_holiday_event():
    """'설날|2027' 같은 형식의 현재 명절 이벤트를 반환합니다."""
    raw = get_service_setting("active_holiday_event", "")
    if "|" not in raw:
        return None
    holiday, year_text = raw.split("|", 1)
    holiday = holiday.strip()
    try:
        year = int(year_text.strip())
    except ValueError:
        return None
    if holiday not in ("설날", "추석"):
        return None
    return {"holiday": holiday, "year": year, "event_key": f"holiday_{'seollal' if holiday == '설날' else 'chuseok'}_{year}"}


def set_active_holiday_event(holiday, year):
    holiday = str(holiday or "").strip()
    year = int(year)
    if holiday not in ("설날", "추석"):
        raise ValueError("명절은 설날 또는 추석만 선택할 수 있습니다.")
    if year < 2026 or year > 2100:
        raise ValueError("행사 연도를 확인해 주세요.")
    save_service_setting("active_holiday_event", f"{holiday}|{year}")
    return get_active_holiday_event()


def close_holiday_event():
    save_service_setting("active_holiday_event", "")


