def loyal_customer_candidates(lookback_days=180, limit=50):
    """최근 방문 상위 고객 후보군. 동률이면 누적 방문과 최근 방문순으로 정렬합니다."""
    lookback_days = max(30, min(int(lookback_days or 180), 730))
    limit = max(1, min(int(limit or 50), 500))
    cutoff = (_customer_now().date() - timedelta(days=lookback_days - 1)).isoformat()
    init_customer_db()
    with _customer_connect() as conn:
        rows = conn.execute(
            """
            SELECT
                c.code,
                c.nickname,
                c.visit_count,
                c.last_visit_at,
                COUNT(v.id) AS recent_visits
            FROM customers c
            LEFT JOIN customer_visit_history v
              ON v.customer_code = c.code
             AND v.visit_date >= ?
            GROUP BY c.code, c.nickname, c.visit_count, c.last_visit_at
            ORDER BY recent_visits DESC, c.visit_count DESC, c.last_visit_at DESC
            LIMIT ?
            """,
            (cutoff, limit),
        ).fetchall()
    return [dict(row) for row in rows]


