def get_event_draw(event_key):
    event_key = str(event_key or "").strip()
    if not event_key:
        return None
    init_customer_db()
    with _customer_connect() as conn:
        draw = conn.execute(
            """
            SELECT id, event_key, event_name, prize_text, eligibility_rule,
                   candidate_count, winner_count, drawn_at, created_at
            FROM event_draws
            WHERE event_key = ?
            """,
            (event_key,),
        ).fetchone()
        if draw is None:
            return None

        winners = conn.execute(
            """
            SELECT w.winner_order, w.customer_code, c.nickname, c.visit_count, c.last_visit_at
            FROM event_winners w
            LEFT JOIN customers c ON c.code = w.customer_code
            WHERE w.draw_id = ?
            ORDER BY w.winner_order ASC
            """,
            (draw["id"],),
        ).fetchall()

    result = dict(draw)
    result["winners"] = [dict(row) for row in winners]
    return result


def create_event_draw(event_key, event_name, prize_text, candidates, winner_count, eligibility_rule):
    """후보군에서 무작위 추첨하고 한 번의 결과를 DB에 고정 저장합니다."""
    event_key = str(event_key or "").strip()[:120]
    event_name = str(event_name or "").strip()[:200]
    prize_text = str(prize_text or "").strip()[:1000]
    eligibility_rule = str(eligibility_rule or "").strip()[:1000]
    winner_count = max(1, min(int(winner_count or 1), 100))

    if not event_key or not event_name:
        raise ValueError("이벤트 정보가 부족합니다.")

    existing = get_event_draw(event_key)
    if existing:
        return existing, False

    dedup = []
    seen = set()
    for item in candidates or []:
        code = str(item.get("code", "") or "").strip().upper()
        if code and code not in seen:
            seen.add(code)
            dedup.append(dict(item))

    if not dedup:
        raise ValueError("추첨 가능한 고객이 없습니다.")

    actual_winners = min(winner_count, len(dedup))
    picked = secrets.SystemRandom().sample(dedup, actual_winners)
    now = _customer_now_text()

    init_customer_db()
    with _customer_connect() as conn:
        cursor = conn.execute(
            """
            INSERT INTO event_draws
            (event_key, event_name, prize_text, eligibility_rule,
             candidate_count, winner_count, drawn_at, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                event_key,
                event_name,
                prize_text,
                eligibility_rule,
                len(dedup),
                actual_winners,
                now,
                now,
            ),
        )
        draw_id = int(cursor.lastrowid)
        for order, item in enumerate(picked, start=1):
            conn.execute(
                """
                INSERT INTO event_winners
                (draw_id, customer_code, winner_order, created_at)
                VALUES (?, ?, ?, ?)
                """,
                (draw_id, str(item.get("code", "")).strip().upper(), order, now),
            )
        conn.commit()

    return get_event_draw(event_key), True


