def render_customer_event_notices(profile=None):
    """고객 화면에는 현재 진행 중인 행사와 본인 당첨 결과만 보여줍니다."""
    growth = growth_event_status()
    active_growth = int(growth.get("active", 0) or 0)
    if active_growth:
        _growth_prize = escape(str(growth_prize_text(active_growth)))
        st.markdown(
            f"""
            <div class="customer-event-banner growth">
                <div class="event-title">🎊 등록 고객 {active_growth}명 돌파 감사 이벤트 진행 중</div>
                <div class="event-detail">🎁 {_growth_prize}</div>
            </div>
            """,
            unsafe_allow_html=True,
        )

    holiday = get_active_holiday_event()
    if holiday:
        _holiday_year = escape(str(holiday.get("year", "")))
        _holiday_name = escape(str(holiday.get("holiday", "")))
        _holiday_prize = escape(str(holiday_prize_text(holiday.get("holiday", ""))))
        st.markdown(
            f"""
            <div class="customer-event-banner">
                <div class="event-title">🧧 {_holiday_year}년 {_holiday_name} 단골 감사 경품 행사 진행 중</div>
                <div class="event-detail">🎁 {_holiday_prize} · 최근 방문이 많은 고객을 우대하는 후보군에서 무작위 추첨합니다.</div>
            </div>
            """,
            unsafe_allow_html=True,
        )

    if profile and profile.get("code"):
        wins = customer_event_wins(profile.get("code"), 10)
        for win in wins:
            st.success(
                f"🎉 당첨을 축하합니다! {win.get('event_name', '감사 이벤트')} · "
                f"{win.get('prize_text', '경품')} · "
                "관리자 안내에 따라 수령해 주세요."
            )


