# v3.2.0 : 희망 이야기 · 다시 시작
# =========================================================

def submit_hope_story(profile, category, title, story, action_text="", anonymous=True):
    """등록 고객의 희망 이야기를 관리자 검토 대기 상태로 저장합니다."""
    if not profile or not profile.get("code"):
        raise ValueError("희망 이야기는 등록 고객만 제출할 수 있습니다.")

    category = str(category or "").strip()
    if category not in HOPE_STORY_CATEGORIES:
        raise ValueError("이야기 분야를 선택해 주세요.")

    title = " ".join(str(title or "").split()).strip()[:60]
    story = str(story or "").strip()[:600]
    action_text = str(action_text or "").strip()[:240]

    if len(title) < 2:
        raise ValueError("제목을 2자 이상 적어 주세요.")
    if len(story) < 20:
        raise ValueError("이야기를 20자 이상 적어 주세요.")

    now = _customer_now_text()
    code = str(profile.get("code", "")).strip().upper()

    init_customer_db()
    with _customer_connect() as conn:
        cursor = conn.execute(
            """
            INSERT INTO hope_stories
            (customer_code, category, title, story, action_text,
             anonymous, status, reward_label, admin_note,
             created_at, reviewed_at, approved_at)
            VALUES (?, ?, ?, ?, ?, ?, '검토중', '', '', ?, '', '')
            """,
            (
                code,
                category,
                title,
                story,
                action_text,
                1 if anonymous else 0,
                now,
            ),
        )
        conn.commit()
        story_id = int(cursor.lastrowid)
    return story_id


def get_approved_hope_stories(limit=6):
    """고객 화면에 공개할 승인된 희망 이야기를 반환합니다."""
    safe_limit = max(1, min(int(limit or 6), 30))
    init_customer_db()
    with _customer_connect() as conn:
        rows = conn.execute(
            """
            SELECT
                h.id, h.category, h.title, h.story, h.action_text,
                h.anonymous, h.reward_label, h.created_at, h.approved_at,
                c.nickname
            FROM hope_stories h
            LEFT JOIN customers c ON c.code = h.customer_code
            WHERE h.status = '승인'
            ORDER BY h.id DESC
            LIMIT ?
            """,
            (safe_limit,),
        ).fetchall()
    return [dict(row) for row in rows]


def get_pending_hope_stories(limit=100):
    """관리자 검토용 희망 이야기 목록."""
    safe_limit = max(1, min(int(limit or 100), 300))
    init_customer_db()
    with _customer_connect() as conn:
        rows = conn.execute(
            """
            SELECT
                h.id, h.customer_code, h.category, h.title, h.story,
                h.action_text, h.anonymous, h.status, h.reward_label,
                h.admin_note, h.created_at, h.reviewed_at,
                c.nickname, c.visit_count
            FROM hope_stories h
            LEFT JOIN customers c ON c.code = h.customer_code
            WHERE h.status = '검토중'
            ORDER BY h.id ASC
            LIMIT ?
            """,
            (safe_limit,),
        ).fetchall()
    return [dict(row) for row in rows]


def get_customer_hope_stories(customer_code, limit=20):
    customer_code = str(customer_code or "").strip().upper()
    if not customer_code:
        return []
    safe_limit = max(1, min(int(limit or 20), 100))
    init_customer_db()
    with _customer_connect() as conn:
        rows = conn.execute(
            """
            SELECT id, category, title, status, reward_label,
                   admin_note, created_at, reviewed_at
            FROM hope_stories
            WHERE customer_code = ?
            ORDER BY id DESC
            LIMIT ?
            """,
            (customer_code, safe_limit),
        ).fetchall()
    return [dict(row) for row in rows]


def review_hope_story(story_id, decision, admin_note="", reward_label="🌈 희망 배지"):
    """관리자가 희망 이야기를 승인 또는 보류합니다."""
    story_id = int(story_id)
    decision = str(decision or "").strip()
    if decision not in ("승인", "보류"):
        raise ValueError("승인 또는 보류를 선택해 주세요.")

    admin_note = str(admin_note or "").strip()[:300]
    reward_label = str(reward_label or "").strip()[:60] if decision == "승인" else ""
    now = _customer_now_text()

    init_customer_db()
    with _customer_connect() as conn:
        exists = conn.execute(
            "SELECT id FROM hope_stories WHERE id = ?",
            (story_id,),
        ).fetchone()
        if not exists:
            raise ValueError("희망 이야기를 찾지 못했습니다.")

        conn.execute(
            """
            UPDATE hope_stories
            SET status = ?,
                reward_label = ?,
                admin_note = ?,
                reviewed_at = ?,
                approved_at = CASE WHEN ? = '승인' THEN ? ELSE approved_at END
            WHERE id = ?
            """,
            (
                decision,
                reward_label,
                admin_note,
                now,
                decision,
                now,
                story_id,
            ),
        )
        conn.commit()
    return True


def hope_story_counts():
    init_customer_db()
    with _customer_connect() as conn:
        row = conn.execute(
            """
            SELECT
                COUNT(*) AS total,
                SUM(CASE WHEN status = '검토중' THEN 1 ELSE 0 END) AS pending,
                SUM(CASE WHEN status = '승인' THEN 1 ELSE 0 END) AS approved,
                SUM(CASE WHEN status = '보류' THEN 1 ELSE 0 END) AS held
            FROM hope_stories
            """
        ).fetchone()
    return {
        "total": int(row["total"] or 0),
        "pending": int(row["pending"] or 0),
        "approved": int(row["approved"] or 0),
        "held": int(row["held"] or 0),
    }


