# v2.0.0 : 추천/제휴 링크 관리
# =========================================================

AFFILIATE_CATEGORIES = [
    "전체·공통",
    "일·직업·이직",
    "사업·자영업",
    "부부·연애",
    "자녀·가족",
    "인간관계",
    "은퇴·노후",
    "배움·새로운 활동",
    "이사·환경 변화",
]

AFFILIATE_LINK_TYPES = ["일반 추천", "제휴·광고"]


def _safe_affiliate_url(url):
    url = str(url or "").strip()
    if not (url.startswith("https://") or url.startswith("http://")):
        raise ValueError("추천 링크는 http:// 또는 https://로 시작해야 합니다.")
    if len(url) > 1000:
        raise ValueError("추천 링크가 너무 깁니다.")
    return url


def add_affiliate_link(category, link_type, title, description, url):
    init_customer_db()
    category = str(category or "전체·공통").strip()
    if category not in AFFILIATE_CATEGORIES:
        category = "전체·공통"
    link_type = str(link_type or "일반 추천").strip()
    if link_type not in AFFILIATE_LINK_TYPES:
        link_type = "일반 추천"
    title = str(title or "").strip()[:80]
    description = str(description or "").strip()[:240]
    url = _safe_affiliate_url(url)
    if not title:
        raise ValueError("추천 제목을 입력해 주세요.")

    with _customer_connect() as conn:
        conn.execute(
            """
            INSERT INTO affiliate_links
            (category, link_type, title, description, url, active, created_at)
            VALUES (?, ?, ?, ?, ?, 1, ?)
            """,
            (category, link_type, title, description, url, _customer_now_text()),
        )
        conn.commit()


def set_affiliate_link_active(link_id, active):
    init_customer_db()
    with _customer_connect() as conn:
        conn.execute(
            "UPDATE affiliate_links SET active = ? WHERE id = ?",
            (1 if active else 0, int(link_id)),
        )
        conn.commit()


def record_affiliate_click(link_id):
    """추천 링크 열기 버튼 사용 횟수만 익명 집계합니다."""
    init_customer_db()
    now = _customer_now_text()
    with _customer_connect() as conn:
        conn.execute(
            """
            UPDATE affiliate_links
            SET click_count = click_count + 1,
                last_clicked_at = ?
            WHERE id = ?
            """,
            (now, int(link_id)),
        )
        conn.commit()


def affiliate_click_summary(limit=10):
    """관리자용 클릭 통계. 고객 식별 정보는 저장하거나 반환하지 않습니다."""
    init_customer_db()
    safe_limit = max(1, min(int(limit or 10), 50))
    with _customer_connect() as conn:
        totals = conn.execute(
            """
            SELECT
                COALESCE(SUM(click_count), 0) AS total_clicks,
                COALESCE(SUM(CASE WHEN click_count > 0 THEN 1 ELSE 0 END), 0) AS clicked_links
            FROM affiliate_links
            """
        ).fetchone()
        rows = conn.execute(
            """
            SELECT id, category, link_type, title, click_count, last_clicked_at, active
            FROM affiliate_links
            ORDER BY click_count DESC, id DESC
            LIMIT ?
            """,
            (safe_limit,),
        ).fetchall()

    return {
        "total_clicks": int(totals["total_clicks"] or 0),
        "clicked_links": int(totals["clicked_links"] or 0),
        "rows": [dict(row) for row in rows],
    }


def get_affiliate_links(category=None, include_inactive=False, limit=20):
    init_customer_db()
    safe_limit = max(1, min(int(limit or 20), 100))
    category = str(category or "").strip()

    where = []
    params = []
    if not include_inactive:
        where.append("active = 1")
    if category:
        if category in AFFILIATE_CATEGORIES and category != "전체·공통":
            where.append("(category = ? OR category = '전체·공통')")
            params.append(category)
        else:
            where.append("category = '전체·공통'")

    where_sql = (" WHERE " + " AND ".join(where)) if where else ""
    params.append(safe_limit)
    with _customer_connect() as conn:
        rows = conn.execute(
            f"""
            SELECT id, category, link_type, title, description, url, active, click_count, last_clicked_at, created_at
            FROM affiliate_links
            {where_sql}
            ORDER BY active DESC, id DESC
            LIMIT ?
            """,
            tuple(params),
        ).fetchall()
    return [dict(row) for row in rows]


def recommendation_category_for_question(question_category):
    """사용자가 직접 선택한 질문 분야만 활용합니다. 건강·재정은 공통 추천만 표시합니다."""
    q = str(question_category or "").strip()
    if q in AFFILIATE_CATEGORIES and q != "전체·공통":
        return q
    return "전체·공통"


def show_affiliate_recommendations(question_category, key_prefix):
    """관리자가 등록한 링크가 있을 때만 최대 3개를 표시합니다."""
    category = recommendation_category_for_question(question_category)
    links = get_affiliate_links(category=category, include_inactive=False, limit=3)
    if not links:
        return

    st.markdown("### 🛍️ 함께 볼 만한 추천")
    st.caption(
        "사주나 타로가 구매를 요구한다는 뜻이 아닙니다. "
        "사용자가 직접 선택한 관심 분야에 맞춰 운영자가 등록한 참고 링크입니다."
    )

    for idx, item in enumerate(links):
        link_type = str(item.get("link_type", "일반 추천") or "일반 추천")
        with st.container(border=True):
            badge = "📌 일반 추천" if link_type == "일반 추천" else "💰 제휴·광고"
            st.markdown(f"**{item.get('title', '추천')}** · {badge}")
            if item.get("description"):
                st.write(item.get("description"))
            st.caption(f"분야: {item.get('category', '전체·공통')}")

            if link_type == "제휴·광고":
                st.info(
                    "광고/제휴 안내: 이 링크를 통해 구매·가입이 이루어지면 "
                    "운영자에게 일정 수수료가 지급될 수 있습니다."
                )

            ready_key = f"{key_prefix}_affiliate_ready_{item.get('id')}_{idx}"
            if st.button(
                "🔗 추천 링크 열기",
                width="stretch",
                key=f"{key_prefix}_affiliate_track_{item.get('id')}_{idx}",
            ):
                record_affiliate_click(item.get("id"))
                st.session_state[ready_key] = True

            if st.session_state.get(ready_key):
                st.link_button(
                    "➡️ 실제 페이지 열기",
                    item.get("url", ""),
                    width="stretch",
                    key=f"{key_prefix}_affiliate_go_{item.get('id')}_{idx}",
                )
                st.caption(
                    "클릭 통계는 위의 '추천 링크 열기' 버튼을 누른 횟수입니다. "
                    "실제 구매·가입 여부는 이 앱에서 확인하지 않습니다."
                )


