HOUR_BRANCH_LABELS = {
    "子": "자시",
    "丑": "축시",
    "寅": "인시",
    "卯": "묘시",
    "辰": "진시",
    "巳": "사시",
    "午": "오시",
    "未": "미시",
    "申": "신시",
    "酉": "유시",
    "戌": "술시",
    "亥": "해시",
}


def branch_from_solar_minutes(total_minutes):
    """경도 보정 시각의 시·분을 전통적인 2시간 지지 구간으로 표시합니다."""
    m = int(total_minutes) % 1440
    if m >= 23 * 60 or m < 1 * 60:
        return "子"
    if m < 3 * 60:
        return "丑"
    if m < 5 * 60:
        return "寅"
    if m < 7 * 60:
        return "卯"
    if m < 9 * 60:
        return "辰"
    if m < 11 * 60:
        return "巳"
    if m < 13 * 60:
        return "午"
    if m < 15 * 60:
        return "未"
    if m < 17 * 60:
        return "申"
    if m < 19 * 60:
        return "酉"
    if m < 21 * 60:
        return "戌"
    return "亥"


def get_hour_time_basis(birth, longitude, yaja_mode, hour_pillar):
    """
    korean-saju가 사용하는 표준 자오선 135° 기준 경도 보정값을 사람이 읽기 쉽게 설명합니다.
    이 화면은 계산 결과를 재계산하는 엔진이 아니라, 이미 계산된 시주를 이해하기 위한 보조 설명입니다.
    """
    offset_minutes = (float(longitude) - 135.0) * 4.0
    solar_birth = birth + timedelta(minutes=offset_minutes)
    solar_total_minutes = solar_birth.hour * 60 + solar_birth.minute
    reference_branch = branch_from_solar_minutes(solar_total_minutes)
    computed_branch = hour_pillar[1] if len(hour_pillar) >= 2 else ""

    # 2시간 지지 구간 경계: 23, 01, 03, ... 21시
    boundaries = [0, 60, 180, 300, 420, 540, 660, 780, 900, 1020, 1140, 1260, 1380]
    nearest_boundary = min(
        boundaries,
        key=lambda b: min(abs(solar_total_minutes - b), 1440 - abs(solar_total_minutes - b)),
    )
    boundary_distance = min(
        abs(solar_total_minutes - nearest_boundary),
        1440 - abs(solar_total_minutes - nearest_boundary),
    )

    if boundary_distance <= 10:
        boundary_status = "경계 매우 가까움"
        boundary_message = (
            f"보정 시각이 시주 경계에서 약 {boundary_distance}분 거리입니다. "
            "출생시각 기록이 몇 분 정도 달라져도 시주가 바뀔 수 있으므로 원기록을 확인하는 것이 좋습니다."
        )
    elif boundary_distance <= 30:
        boundary_status = "경계 주의"
        boundary_message = (
            f"보정 시각이 시주 경계에서 약 {boundary_distance}분 거리입니다. "
            "출생시각이 대략적으로 기록된 경우 경계 전후를 함께 확인해 볼 수 있습니다."
        )
    else:
        boundary_status = "경계 여유"
        boundary_message = (
            f"보정 시각은 가장 가까운 시주 경계에서 약 {boundary_distance}분 떨어져 있습니다."
        )

    if reference_branch == "子" and solar_birth.hour == 23:
        zashi_status = "야자시(23:00~24:00)"
        if yaja_mode:
            yaja_message = (
                "현재 '야자시 분리법 사용'이 켜져 있습니다. "
                "이 구간에서는 야자시를 당일 일주 쪽으로 분리해 적용합니다."
            )
        else:
            yaja_message = (
                "현재 '야자시 분리법 사용'이 꺼져 있습니다. "
                "이 구간에서는 야자시를 다음날 일주 쪽으로 통합해 적용합니다."
            )
    elif reference_branch == "子" and solar_birth.hour == 0:
        zashi_status = "조자시(00:00~01:00)"
        yaja_message = (
            "조자시 구간입니다. 이 구간은 야자시 분리 옵션의 차이보다 "
            "보정된 날짜와 자시 적용 기준이 중요합니다."
        )
    else:
        zashi_status = "자시 외 구간"
        yaja_message = (
            "현재 보정 시각은 야자시·조자시 구간이 아니므로 "
            "야자시 분리 옵션이 일주에 직접 영향을 주는 구간은 아닙니다."
        )

    if solar_birth.date() != birth.date():
        date_shift_message = (
            f"KST 입력 날짜({birth:%Y-%m-%d})와 경도 보정 후 참고 날짜"
            f"({solar_birth:%Y-%m-%d})가 다릅니다. 자정 부근 출생은 이 차이를 특히 확인하세요."
        )
    else:
        date_shift_message = (
            "KST 입력 날짜와 경도 보정 후 참고 날짜가 같습니다."
        )

    consistency = "일치" if reference_branch == computed_branch else "추가 확인"

    return {
        "offset_minutes": offset_minutes,
        "solar_birth": solar_birth,
        "solar_time_text": solar_birth.strftime("%Y-%m-%d %H:%M"),
        "reference_branch": reference_branch,
        "reference_branch_label": HOUR_BRANCH_LABELS.get(reference_branch, reference_branch),
        "computed_branch": computed_branch,
        "computed_branch_label": HOUR_BRANCH_LABELS.get(computed_branch, computed_branch),
        "consistency": consistency,
        "boundary_distance": int(boundary_distance),
        "boundary_status": boundary_status,
        "boundary_message": boundary_message,
        "zashi_status": zashi_status,
        "yaja_message": yaja_message,
        "date_shift_message": date_shift_message,
    }


