def hanja_to_korean(text):
    return "".join(HANJA_TO_KOREAN.get(char, char) for char in str(text))


def count_five_elements(year, month, day, hour):
    counts = {"목": 0, "화": 0, "토": 0, "금": 0, "수": 0}
    for char in f"{year}{month}{day}{hour}":
        element = FIVE_ELEMENTS.get(char)
        if element:
            counts[element] += 1
    return counts


def get_ten_god(day_stem, target_stem):
    day_element, day_yinyang, _ = STEM_INFO[day_stem]
    target_element, target_yinyang, _ = STEM_INFO[target_stem]
    same_yinyang = day_yinyang == target_yinyang

    if day_element == target_element:
        return "비견" if same_yinyang else "겁재"
    if GENERATES[day_element] == target_element:
        return "식신" if same_yinyang else "상관"
    if CONTROLS[day_element] == target_element:
        return "편재" if same_yinyang else "정재"
    if CONTROLS[target_element] == day_element:
        return "편관" if same_yinyang else "정관"
    if GENERATES[target_element] == day_element:
        return "편인" if same_yinyang else "정인"
    return "-"


# =========================================================
# 33단계 : 출생시간 미상 - 12개 시진 후보 비교
# =========================================================

HOUR_CANDIDATE_SPECS = [
    ("子", "자시", 0, 23 * 60),
    ("丑", "축시", 2, 1 * 60),
    ("寅", "인시", 4, 3 * 60),
    ("卯", "묘시", 6, 5 * 60),
    ("辰", "진시", 8, 7 * 60),
    ("巳", "사시", 10, 9 * 60),
    ("午", "오시", 12, 11 * 60),
    ("未", "미시", 14, 13 * 60),
    ("申", "신시", 16, 15 * 60),
    ("酉", "유시", 18, 17 * 60),
    ("戌", "술시", 20, 19 * 60),
    ("亥", "해시", 22, 21 * 60),
]


def _clock_text(total_minutes):
    total = int(round(total_minutes)) % 1440
    return f"{total // 60:02d}:{total % 60:02d}"


def build_birth_time_candidates(birth_date, longitude, solar_terms, base_day_pillar):
    """
    출생시간을 모를 때 12개 시진의 중앙 시각을 대표값으로 넣어 후보 시주를 비교합니다.
    각 후보의 KST 대표시각은 출생지 경도 보정값을 역산해 전통 시진의 중앙에 오도록 잡습니다.
    정확한 출생시각을 복원하는 기능이 아니라 '어떤 항목이 시간에 따라 달라지는가'를 보는 비교표입니다.
    """
    offset_minutes = (float(longitude) - 135.0) * 4.0
    rows = []

    for expected_branch, label, solar_mid_hour, solar_start_minutes in HOUR_CANDIDATE_SPECS:
        solar_midpoint = datetime(
            birth_date.year, birth_date.month, birth_date.day, solar_mid_hour, 0
        )
        candidate_kst = solar_midpoint - timedelta(minutes=offset_minutes)

        candidate_saju = Saju.from_birth(
            kst_moment=candidate_kst,
            solar_terms=solar_terms,
            longitude=longitude,
            yaja_si_separated=True,
        )

        cand_day = candidate_saju.day_pillar.hanja
        cand_hour = candidate_saju.hour_pillar.hanja
        cand_hour_stem = cand_hour[0]
        cand_hour_branch = cand_hour[1]
        cand_ten_god = get_ten_god(cand_day[0], cand_hour_stem)

        hidden = HIDDEN_STEMS.get(cand_hour_branch, [])
        hidden_text = " ".join(
            f"{stem}({get_ten_god(cand_day[0], stem)})" for stem in hidden
        ) or "-"

        stem_element = FIVE_ELEMENTS.get(cand_hour_stem, "-")
        branch_element = FIVE_ELEMENTS.get(cand_hour_branch, "-")

        # 전통 시진의 보정시각 구간을 해당 출생지의 KST 시계로 환산한 대략 범위
        kst_start = solar_start_minutes - offset_minutes
        kst_end = solar_start_minutes + 120 - offset_minutes
        kst_range = f"{_clock_text(kst_start)}~{_clock_text(kst_end)}"

        rows.append({
            "시진": f"{expected_branch} · {label}",
            "대략 KST 구간": kst_range,
            "대표 KST": candidate_kst.strftime("%H:%M"),
            "후보 시주": cand_hour,
            "한글": hanja_to_korean(cand_hour),
            "시주 천간 십신": cand_ten_god,
            "시지 지장간(십신)": hidden_text,
            "시주 오행": f"{stem_element}·{branch_element}",
            "일주": cand_day,
            "일주 변화": "같음" if cand_day == base_day_pillar else "변경 가능",
            "계산 시지": cand_hour_branch,
            "_candidate_kst": candidate_kst,
        })

    # 같은 子시라도 23시대 야자시는 날짜 경계 문제를 따로 확인합니다.
    late_solar = datetime(
        birth_date.year, birth_date.month, birth_date.day, 23, 30
    )
    late_kst = late_solar - timedelta(minutes=offset_minutes)
    late_modes = []
    for mode, mode_label in [(True, "야자시 분리 사용"), (False, "야자시 분리 사용 안 함")]:
        late_saju = Saju.from_birth(
            kst_moment=late_kst,
            solar_terms=solar_terms,
            longitude=longitude,
            yaja_si_separated=mode,
        )
        late_modes.append({
            "기준": mode_label,
            "대표 KST": late_kst.strftime("%H:%M"),
            "일주": late_saju.day_pillar.hanja,
            "시주": late_saju.hour_pillar.hanja,
        })

    return rows, late_modes


def build_virtual_candidate_analysis(
    candidate_kst,
    longitude,
    solar_terms,
    gender_value,
    birth_date,
    current_year,
):
    """선택한 시진 대표시각을 가정해 핵심 사주 항목을 다시 계산합니다."""
    candidate_saju = Saju.from_birth(
        kst_moment=candidate_kst,
        solar_terms=solar_terms,
        longitude=longitude,
        yaja_si_separated=True,
    )
    candidate_analysis = SajuAnalysis(candidate_saju)

    year_p = candidate_saju.year_pillar.hanja
    month_p = candidate_saju.month_pillar.hanja
    day_p = candidate_saju.day_pillar.hanja
    hour_p = candidate_saju.hour_pillar.hanja

    pillars = {
        "연주": year_p,
        "월주": month_p,
        "일주": day_p,
        "시주": hour_p,
    }

    day_stem = day_p[0]
    day_element = STEM_INFO[day_stem][0]

    resource_element = next(
        element for element, generated in GENERATES.items()
        if generated == day_element
    )
    output_element = GENERATES[day_element]
    wealth_element = CONTROLS[day_element]
    officer_element = next(
        element for element, controlled in CONTROLS.items()
        if controlled == day_element
    )

    element_counts = count_five_elements(year_p, month_p, day_p, hour_p)

    ten_god_rows = []
    for label, pillar in [
        ("시주", hour_p),
        ("일주", day_p),
        ("월주", month_p),
        ("연주", year_p),
    ]:
        ten_god_rows.append({
            "구분": label,
            "천간": pillar[0],
            "한글": STEM_INFO[pillar[0]][2],
            "십신": get_ten_god(day_stem, pillar[0]),
        })

    hidden_rows = []
    for label, pillar in [
        ("시주", hour_p),
        ("일주", day_p),
        ("월주", month_p),
        ("연주", year_p),
    ]:
        branch = pillar[1]
        for hidden_stem in HIDDEN_STEMS.get(branch, []):
            hidden_rows.append({
                "구분": label,
                "지지": branch,
                "지장간": hidden_stem,
                "한글": STEM_INFO[hidden_stem][2],
                "십신": get_ten_god(day_stem, hidden_stem),
            })

    weighted_elements = [
        (FIVE_ELEMENTS[year_p[0]], 1.0),
        (FIVE_ELEMENTS[month_p[0]], 1.0),
        (FIVE_ELEMENTS[day_p[0]], 1.0),
        (FIVE_ELEMENTS[hour_p[0]], 1.0),
        (FIVE_ELEMENTS[year_p[1]], 1.0),
        (FIVE_ELEMENTS[month_p[1]], 2.0),
        (FIVE_ELEMENTS[day_p[1]], 1.0),
        (FIVE_ELEMENTS[hour_p[1]], 1.0),
    ]
    support_score = sum(
        weight for element, weight in weighted_elements
        if element in [day_element, resource_element]
    )
    total_score = sum(weight for _, weight in weighted_elements)
    support_ratio = support_score / total_score * 100 if total_score else 0.0

    if support_ratio >= 60:
        basic_strength = "신강 쪽 기초 경향"
    elif support_ratio <= 40:
        basic_strength = "신약 쪽 기초 경향"
    else:
        basic_strength = "중간·균형권 기초 경향"

    relation_rows = []
    stem_positions = [
        ("시주", hour_p[0]),
        ("일주", day_p[0]),
        ("월주", month_p[0]),
        ("연주", year_p[0]),
    ]
    branch_positions = [
        ("시주", hour_p[1]),
        ("일주", day_p[1]),
        ("월주", month_p[1]),
        ("연주", year_p[1]),
    ]

    for i in range(len(stem_positions)):
        for j in range(i + 1, len(stem_positions)):
            pos1, stem1 = stem_positions[i]
            pos2, stem2 = stem_positions[j]
            pair = frozenset([stem1, stem2])
            if pair in STEM_COMBINATIONS:
                relation_name, change_element = STEM_COMBINATIONS[pair]
                relation_rows.append({
                    "종류": "천간합",
                    "위치": f"{pos1} ↔ {pos2}",
                    "구성": f"{stem1} + {stem2}",
                    "관계": relation_name,
                    "참고": f"전통적 화 방향: {change_element}",
                })

    for i in range(len(branch_positions)):
        for j in range(i + 1, len(branch_positions)):
            pos1, branch1 = branch_positions[i]
            pos2, branch2 = branch_positions[j]
            pair = frozenset([branch1, branch2])
            pair_text = f"{branch1} + {branch2}"
            pos_text = f"{pos1} ↔ {pos2}"

            if pair in BRANCH_CLASHES:
                relation_rows.append({
                    "종류": "지지충", "위치": pos_text, "구성": pair_text,
                    "관계": BRANCH_CLASHES[pair], "참고": "육충",
                })
            if pair in BRANCH_COMBINATIONS:
                name, element = BRANCH_COMBINATIONS[pair]
                relation_rows.append({
                    "종류": "지지육합", "위치": pos_text, "구성": pair_text,
                    "관계": name, "참고": f"전통적 화 방향: {element}",
                })
            if pair in BRANCH_HARMS:
                relation_rows.append({
                    "종류": "지지해", "위치": pos_text, "구성": pair_text,
                    "관계": BRANCH_HARMS[pair], "참고": "",
                })
            if pair in BRANCH_BREAKS:
                relation_rows.append({
                    "종류": "지지파", "위치": pos_text, "구성": pair_text,
                    "관계": BRANCH_BREAKS[pair], "참고": "",
                })

    branch_list = [p[1] for _, p in [("시주", hour_p), ("일주", day_p), ("월주", month_p), ("연주", year_p)]]
    branch_set = set(branch_list)

    for combination_set, data in THREE_COMBINATIONS.items():
        name, element, composition = data
        if combination_set.issubset(branch_set):
            relation_rows.append({
                "종류": "지지삼합", "위치": "원국", "구성": composition,
                "관계": name, "참고": f"오행: {element}",
            })

    if set(["寅", "巳", "申"]).issubset(branch_set):
        relation_rows.append({
            "종류": "지지형", "위치": "원국", "구성": "寅 + 巳 + 申",
            "관계": "인사신 삼형", "참고": "",
        })
    if set(["丑", "戌", "未"]).issubset(branch_set):
        relation_rows.append({
            "종류": "지지형", "위치": "원국", "구성": "丑 + 戌 + 未",
            "관계": "축술미 삼형", "참고": "",
        })
    if set(["子", "卯"]).issubset(branch_set):
        relation_rows.append({
            "종류": "지지형", "위치": "원국", "구성": "子 + 卯",
            "관계": "자묘형", "참고": "",
        })
    for branch, name in SELF_PUNISHMENT.items():
        count = branch_list.count(branch)
        if count >= 2:
            relation_rows.append({
                "종류": "지지형", "위치": "원국", "구성": f"{branch} × {count}",
                "관계": name, "참고": "자형",
            })

    # 후보 시각 기준 대운
    candidate_daewoon = Daewoon.compute(
        saju=candidate_saju,
        gender=gender_value,
        solar_terms=solar_terms,
        count=10,
    )
    daewoon_rows = []
    for entry in candidate_daewoon.entries:
        g_hanja = ganji_hanja(entry.gan_ji)
        daewoon_rows.append({
            "시작 나이": age_text(entry.start_age, entry.start_months_offset),
            "대운 간지": g_hanja,
            "한글": hanja_to_korean(g_hanja[:2]) if len(g_hanja) >= 2 else "",
        })

    today = datetime.now().date()
    current_age_months = (
        (today.year - birth_date.year) * 12
        + (today.month - birth_date.month)
    )
    if today.day < birth_date.day:
        current_age_months -= 1

    current_daewoon = None
    for entry in candidate_daewoon.entries:
        start_total_months = entry.start_age * 12 + entry.start_months_offset
        if start_total_months <= current_age_months:
            current_daewoon = entry

    current_daewoon_hanja = "-"
    current_daewoon_korean = "-"
    current_daewoon_ten_god = "-"
    current_daewoon_start = "-"
    if current_daewoon is not None:
        current_daewoon_hanja = ganji_hanja(current_daewoon.gan_ji)
        if len(current_daewoon_hanja) >= 2:
            current_daewoon_korean = hanja_to_korean(current_daewoon_hanja[:2])
            current_daewoon_ten_god = get_ten_god(day_stem, current_daewoon_hanja[0])
        current_daewoon_start = age_text(
            current_daewoon.start_age,
            current_daewoon.start_months_offset,
        )

    # 후보 시각 기준 올해 세운
    candidate_sewoon_entries = Sewoon.compute(
        saju=candidate_saju,
        solar_terms=solar_terms,
        center_year=current_year,
        years_back=1,
        years_forward=1,
    )
    current_sewoon_hanja = "-"
    current_sewoon_korean = "-"
    current_sewoon_ten_god = "-"
    for entry in candidate_sewoon_entries:
        raw_year = getattr(entry, "year", "")
        try:
            year_value = int(raw_year)
        except (TypeError, ValueError):
            year_value = raw_year
        if year_value != current_year:
            continue
        g_value = getattr(entry, "gan_ji", None)
        if g_value is None:
            g_value = getattr(entry, "ganji", None)
        g_hanja = ganji_hanja(g_value) if g_value is not None else ""
        current_sewoon_hanja = g_hanja or "-"
        if len(g_hanja) >= 2:
            current_sewoon_korean = hanja_to_korean(g_hanja[:2])
            current_sewoon_ten_god = get_ten_god(day_stem, g_hanja[0])
        break

    jeonggyeok = getattr(candidate_analysis, "jeonggyeok", None)
    yongsin = getattr(candidate_analysis, "yongsin", None)

    return {
        "candidate_kst": candidate_kst,
        "pillars": pillars,
        "day_master": day_stem,
        "day_master_info": DAY_MASTER_INFO[day_stem],
        "element_counts": element_counts,
        "ten_god_df": pd.DataFrame(ten_god_rows),
        "hidden_df": pd.DataFrame(hidden_rows),
        "basic_strength": basic_strength,
        "support_ratio": support_ratio,
        "relation_df": pd.DataFrame(relation_rows),
        "jeonggyeok": jeonggyeok,
        "yongsin": yongsin,
        "direction_text": "순행" if candidate_daewoon.forward else "역행",
        "daewoon_df": pd.DataFrame(daewoon_rows),
        "current_daewoon_hanja": current_daewoon_hanja,
        "current_daewoon_korean": current_daewoon_korean,
        "current_daewoon_ten_god": current_daewoon_ten_god,
        "current_daewoon_start": current_daewoon_start,
        "current_sewoon_hanja": current_sewoon_hanja,
        "current_sewoon_korean": current_sewoon_korean,
        "current_sewoon_ten_god": current_sewoon_ten_god,
        "day_element": day_element,
        "resource_element": resource_element,
        "output_element": output_element,
        "wealth_element": wealth_element,
        "officer_element": officer_element,
    }


def ganji_hanja(value):
    if value is None:
        return ""
    return getattr(value, "hanja", str(value))


def age_text(start_age, months_offset):
    return f"{start_age}세 {months_offset}개월" if months_offset > 0 else f"{start_age}세"


def add_theme_score(theme_count, ten_god):
    if ten_god in ["정재", "편재"]:
        theme_count["재물"] += 1
    elif ten_god in ["정관", "편관"]:
        theme_count["직업"] += 1
    elif ten_god in ["식신", "상관"]:
        theme_count["활동"] += 1
    elif ten_god in ["비견", "겁재"]:
        theme_count["관계"] += 1
    elif ten_god in ["정인", "편인"]:
        theme_count["학습"] += 1


def make_saju_pdf(report_text, person_name):
    # Windows 한글 폰트를 순서대로 찾아 사용합니다.
    font_candidates = [
        r"C:\Windows\Fonts\malgun.ttf",
        r"C:\Windows\Fonts\malgunsl.ttf",
        r"C:\Windows\Fonts\gulim.ttc",
    ]

    font_path = next(
        (path for path in font_candidates if os.path.exists(path)),
        None,
    )

    if font_path is None:
        return None

    font_name = "SajuKoreanFont"

    if font_name not in pdfmetrics.getRegisteredFontNames():
        try:
            pdfmetrics.registerFont(TTFont(font_name, font_path))
        except Exception:
            return None

    buffer = io.BytesIO()
    pdf = canvas.Canvas(buffer, pagesize=A4)
    page_width, page_height = A4

    left_margin = 45
    right_margin = 45
    top_margin = 50
    bottom_margin = 50
    usable_width = page_width - left_margin - right_margin

    y = page_height - top_margin
    pdf.setFont(font_name, 17)
    display_name = person_name if person_name else "사주"
    pdf.drawString(left_margin, y, f"{display_name}님의 사주 풀이 보고서")
    y -= 35

    def draw_text_line(text):
        nonlocal y

        if text.strip() == "":
            y -= 10
            return

        is_heading = text.startswith("[") and text.endswith("]")
        font_size = 12 if is_heading else 10
        pdf.setFont(font_name, font_size)

        current_line = ""

        for char in text:
            test_line = current_line + char
            width = pdfmetrics.stringWidth(test_line, font_name, font_size)

            if width <= usable_width:
                current_line = test_line
            else:
                if y < bottom_margin:
                    pdf.showPage()
                    y = page_height - top_margin
                    pdf.setFont(font_name, font_size)

                if current_line:
                    pdf.drawString(left_margin, y, current_line)
                    y -= 16
                current_line = char

        if current_line:
            if y < bottom_margin:
                pdf.showPage()
                y = page_height - top_margin
                pdf.setFont(font_name, font_size)

            pdf.drawString(left_margin, y, current_line)
            y -= 16

        if is_heading:
            y -= 5

    for line in report_text.splitlines():
        draw_text_line(line)

    pdf.save()
    buffer.seek(0)
    return buffer.getvalue()


def make_consulting_pdf(report_text, person_name):
    """상담용 문장을 읽기 좋은 A4 보고서로 만듭니다."""
    font_candidates = [
        r"C:\Windows\Fonts\malgun.ttf",
        r"C:\Windows\Fonts\malgunsl.ttf",
        r"C:\Windows\Fonts\gulim.ttc",
        "/usr/share/fonts/truetype/nanum/NanumGothic.ttf",
        "/usr/share/fonts/truetype/unfonts-core/UnDotum.ttf",
    ]
    font_path = next((path for path in font_candidates if os.path.exists(path)), None)
    if font_path is None:
        return None

    font_name = "SajuConsultFont"
    if font_name not in pdfmetrics.getRegisteredFontNames():
        try:
            pdfmetrics.registerFont(TTFont(font_name, font_path))
        except Exception:
            return None

    buffer = io.BytesIO()
    display_name = person_name if person_name else "내담자"

    doc = SimpleDocTemplate(
        buffer,
        pagesize=A4,
        rightMargin=17 * mm,
        leftMargin=17 * mm,
        topMargin=15 * mm,
        bottomMargin=16 * mm,
        title=f"{display_name}님의 사주 상담 보고서",
        author="MIND ALL IN ONE",
        allowSplitting=1,
    )

    navy = colors.HexColor("#24364B")
    navy2 = colors.HexColor("#304C6D")
    accent = colors.HexColor("#456E9F")
    muted = colors.HexColor("#667085")
    text_color = colors.HexColor("#1F2937")
    line = colors.HexColor("#D8DEE8")
    pale = colors.HexColor("#F6F8FB")
    pale_blue = colors.HexColor("#EDF4FC")
    pale_gold = colors.HexColor("#FFF8E8")
    pale_green = colors.HexColor("#EFF8F3")

    title_style = ParagraphStyle(
        "ConsultTitle",
        fontName=font_name,
        fontSize=19,
        leading=24,
        textColor=colors.white,
        wordWrap="CJK",
    )
    title_sub_style = ParagraphStyle(
        "ConsultTitleSub",
        fontName=font_name,
        fontSize=8.8,
        leading=12,
        textColor=colors.HexColor("#E7EEF7"),
        wordWrap="CJK",
    )
    heading_style = ParagraphStyle(
        "ConsultHeading",
        fontName=font_name,
        fontSize=11.4,
        leading=15,
        textColor=navy,
        wordWrap="CJK",
    )
    body_style = ParagraphStyle(
        "ConsultBody",
        fontName=font_name,
        fontSize=9.65,
        leading=15.0,
        textColor=text_color,
        spaceAfter=5,
        wordWrap="CJK",
    )
    bullet_style = ParagraphStyle(
        "ConsultBullet",
        parent=body_style,
        leftIndent=9,
        firstLineIndent=-7,
        spaceAfter=4,
    )
    small_style = ParagraphStyle(
        "ConsultSmall",
        fontName=font_name,
        fontSize=8.45,
        leading=11.5,
        textColor=muted,
        wordWrap="CJK",
    )

    lines = [line_text.rstrip() for line_text in report_text.splitlines()]
    first_nonempty = next((x.strip() for x in lines if x.strip()), "사주 상담 보고서")

    meta = {}
    section_start = 0
    seen_title = False
    for idx, raw in enumerate(lines):
        value = raw.strip()
        if not value:
            continue
        if not seen_title:
            seen_title = True
            continue
        if value.startswith("[") and value.endswith("]"):
            section_start = idx
            break
        if ":" in value:
            key, val = value.split(":", 1)
            meta[key.strip()] = val.strip()

    story = []

    title_panel = Table(
        [[
            Paragraph(escape(first_nonempty), title_style),
            Paragraph(f"쉽게 읽는 상담 안내서<br/>v{APP_VERSION}", title_sub_style),
        ]],
        colWidths=[132 * mm, 44 * mm],
    )
    title_panel.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, -1), navy),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("LEFTPADDING", (0, 0), (-1, -1), 11),
        ("RIGHTPADDING", (0, 0), (-1, -1), 11),
        ("TOPPADDING", (0, 0), (-1, -1), 10),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 10),
        ("ALIGN", (1, 0), (1, 0), "RIGHT"),
    ]))
    story.append(title_panel)
    story.append(Spacer(1, 7))

    meta_pairs = [
        ("이름", meta.get("이름", display_name)),
        ("성별", meta.get("성별", "-")),
        ("입력 생년월일", meta.get("입력 생년월일", "-")),
        ("출생시간", meta.get("출생시간", "-")),
        ("계산 기준일", meta.get("계산 기준일", "-")),
        ("출생지역", meta.get("출생지역", "-")),
    ]
    meta_rows = []
    for i in range(0, len(meta_pairs), 2):
        left_pair = meta_pairs[i]
        right_pair = meta_pairs[i + 1]
        meta_rows.append([
            Paragraph(f"<b>{escape(left_pair[0])}</b>", small_style),
            Paragraph(escape(str(left_pair[1])), small_style),
            Paragraph(f"<b>{escape(right_pair[0])}</b>", small_style),
            Paragraph(escape(str(right_pair[1])), small_style),
        ])

    info_table = Table(meta_rows, colWidths=[27 * mm, 57 * mm, 27 * mm, 57 * mm])
    info_table.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, -1), pale),
        ("BOX", (0, 0), (-1, -1), 0.6, line),
        ("INNERGRID", (0, 0), (-1, -1), 0.35, line),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("LEFTPADDING", (0, 0), (-1, -1), 7),
        ("RIGHTPADDING", (0, 0), (-1, -1), 7),
        ("TOPPADDING", (0, 0), (-1, -1), 5.5),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 5.5),
    ]))
    story.append(info_table)
    story.append(Spacer(1, 7))

    def section_color(label):
        if "한눈에" in label or "강점" in label:
            return pale_blue, accent
        if "한 걸음" in label:
            return pale_gold, colors.HexColor("#B58A2A")
        if "질문" in label or "응원" in label:
            return pale_green, colors.HexColor("#458064")
        if "전문가" in label or "마무리" in label:
            return pale, muted
        return pale_blue, navy2

    for raw in lines[section_start:]:
        value = raw.strip()
        if not value:
            story.append(Spacer(1, 2.5))
            continue

        if value.startswith("[") and value.endswith("]"):
            label = value[1:-1]
            bg_color, border_color = section_color(label)
            section_box = Table(
                [[Paragraph(f"<b>{escape(label)}</b>", heading_style)]],
                colWidths=[176 * mm],
            )
            section_box.setStyle(TableStyle([
                ("BACKGROUND", (0, 0), (-1, -1), bg_color),
                ("BOX", (0, 0), (-1, -1), 0.65, border_color),
                ("LINEBEFORE", (0, 0), (0, -1), 3.2, border_color),
                ("LEFTPADDING", (0, 0), (-1, -1), 10),
                ("RIGHTPADDING", (0, 0), (-1, -1), 9),
                ("TOPPADDING", (0, 0), (-1, -1), 5),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
            ]))
            story.append(Spacer(1, 3))
            story.append(section_box)
            story.append(Spacer(1, 4))
        elif value.startswith("• "):
            story.append(Paragraph("• " + escape(value[2:]), bullet_style))
        elif value.startswith("※"):
            story.append(Spacer(1, 5))
            note_box = Table(
                [[Paragraph(escape(value), small_style)]],
                colWidths=[176 * mm],
            )
            note_box.setStyle(TableStyle([
                ("BACKGROUND", (0, 0), (-1, -1), pale),
                ("BOX", (0, 0), (-1, -1), 0.4, line),
                ("LEFTPADDING", (0, 0), (-1, -1), 8),
                ("RIGHTPADDING", (0, 0), (-1, -1), 8),
                ("TOPPADDING", (0, 0), (-1, -1), 6),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 6),
            ]))
            story.append(note_box)
        else:
            story.append(Paragraph(escape(value), body_style))

    def on_page(pdf_canvas, document):
        pdf_canvas.saveState()
        pdf_canvas.setStrokeColor(line)
        pdf_canvas.setLineWidth(0.45)
        pdf_canvas.line(17 * mm, 12 * mm, A4[0] - 17 * mm, 12 * mm)
        pdf_canvas.setFont(font_name, 7.8)
        pdf_canvas.setFillColor(muted)
        page_no = pdf_canvas.getPageNumber()
        if page_no > 1:
            pdf_canvas.drawString(17 * mm, A4[1] - 9 * mm, f"{display_name}님의 사주 상담 보고서")
        pdf_canvas.drawString(17 * mm, 7.5 * mm, "나를 이해하고 다음 선택을 생각해보는 참고자료")
        pdf_canvas.drawRightString(A4[0] - 17 * mm, 7.5 * mm, f"{page_no}쪽")
        pdf_canvas.restoreState()

    try:
        doc.build(story, onFirstPage=on_page, onLaterPages=on_page)
    except Exception:
        return None

    buffer.seek(0)
    return buffer.getvalue()


