def build_tarot_deck():
    deck = []
    for number, ko, en, upright, reversed_text in MAJOR_ARCANA:
        deck.append({
            "id": f"major-{number}",
            "name": f"{number} {ko}",
            "english": en,
            "upright": upright,
            "reversed": reversed_text,
            "arcana": "메이저",
        })
    for suit_ko, (suit_en, suit_upright, suit_reversed) in MINOR_SUITS.items():
        for rank_ko, rank_en, rank_upright, rank_reversed in MINOR_RANKS:
            deck.append({
                "id": f"{suit_en}-{rank_en}",
                "name": f"{suit_ko} {rank_ko}",
                "english": f"{rank_en} of {suit_en}",
                "upright": f"{suit_upright} · {rank_upright}",
                "reversed": f"{suit_reversed} · {rank_reversed}",
                "arcana": "마이너",
            })
    return deck


