def ensure_tarot_asset_dirs():
    """타로 이미지 폴더를 자동으로 준비합니다."""
    for p in [
        TAROT_MAJOR_DIR,
        TAROT_WANDS_DIR,
        TAROT_CUPS_DIR,
        TAROT_SWORDS_DIR,
        TAROT_PENTACLES_DIR,
    ]:
        p.mkdir(parents=True, exist_ok=True)


def tarot_minor_image_info(card):
    """마이너 아르카나 이미지 경로 계산용 정보를 반환합니다."""
    english = str(card.get("english", "") or "").strip()
    if " of " not in english:
        return None

    rank, suit = [x.strip() for x in english.split(" of ", 1)]
    suit_key = suit.lower()
    if suit_key.endswith("s") is False:
        suit_key = suit_key + "s"

    if suit_key not in SUIT_TO_DIR:
        return None

    rank_file = MINOR_RANK_TO_FILE.get(rank)
    if not rank_file:
        return None

    dir_path = SUIT_TO_DIR[suit_key]
    filename = f"{suit_key}_{rank_file}.png"
    return dir_path / filename


def tarot_card_image_path(card):
    """현재 카드에 연결된 타로 이미지가 있으면 Path를 반환합니다."""
    ensure_tarot_asset_dirs()

    arcana = str(card.get("arcana", "") or "").strip()
    if arcana == "메이저":
        filename = TAROT_MAJOR_IMAGE_FILES.get(str(card.get("english", "") or ""))
        if not filename:
            return None
        path = TAROT_MAJOR_DIR / filename
        return path if path.exists() and path.is_file() else None

    if arcana == "마이너":
        path = tarot_minor_image_info(card)
        if path and path.exists() and path.is_file():
            return path

    return None


@st.cache_data(show_spinner=False)
def tarot_image_data_uri(path_text, modified_ns):
    """로컬 타로 이미지를 브라우저에서 바로 표시할 수 있는 data URI로 변환합니다."""
    path = Path(path_text)
    suffix = path.suffix.lower()
    mime = "image/png"
    if suffix in (".jpg", ".jpeg"):
        mime = "image/jpeg"
    elif suffix == ".webp":
        mime = "image/webp"

    encoded = base64.b64encode(path.read_bytes()).decode("ascii")
    return f"data:{mime};base64,{encoded}"


def hero_banner_path():
    base_dir = Path(__file__).resolve().parent
    for filename in HERO_BANNER_FILE_CANDIDATES:
        candidate = base_dir / filename
        if candidate.exists():
            return candidate
    return None


