def tarot_real_card_item_html(card, label=""):
    """실제 카드 이미지 한 장을 반응형 HTML 카드로 만듭니다."""
    image_path = tarot_card_image_path(card)
    if not image_path:
        # 78장 이미지가 누락된 예외 상황에서는 기존 CSS 카드로 안전하게 대체합니다.
        return tarot_card_visual_html(card, label)

    try:
        modified_ns = image_path.stat().st_mtime_ns
        image_uri = tarot_image_data_uri(str(image_path), modified_ns)
    except Exception:
        return tarot_card_visual_html(card, label)

    name = escape(str(card.get("name", "") or ""))
    english = escape(str(card.get("english", "") or ""))
    orientation = escape(str(card.get("orientation", "정방향") or "정방향"))
    position = escape(str(label or ""))
    reversed_class = " is-reversed" if orientation == "역방향" else ""
    orientation_icon = "↩️" if orientation == "역방향" else "⬆️"

    return f"""
    <div class="tarot-real-item">
        <div class="tarot-real-position">{position}</div>
        <div class="tarot-real-frame">
            <img class="tarot-real-image{reversed_class}"
                 src="{image_uri}"
                 alt="{english}">
        </div>
        <div class="tarot-real-name">{name}</div>
        <div class="tarot-real-english">{english}</div>
        <div class="tarot-real-orientation">{orientation_icon} {orientation}</div>
    </div>
    """


