def tarot_allowed_counts(segment, paid_pass_active=False):
    if paid_pass_active or segment == "단골 고객":
        return [1, 3, 5]
    if segment in ("등록 고객", "재방문 고객"):
        return [1, 3]
    return [1]


def tarot_spread_positions(count):
    if count == 1:
        return ["지금 가장 먼저 볼 메시지"]
    if count == 3:
        return ["현재 상황", "확인할 점", "다음 행동"]
    return ["현재 상황", "핵심 장애", "숨은 자원", "현실 조언", "다음 한 걸음"]


def draw_tarot_cards(count, include_reversed=False):
    rng = secrets.SystemRandom()
    picked = rng.sample(TAROT_DECK, int(count))
    result = []
    for card in picked:
        item = dict(card)
        is_reversed = bool(include_reversed and rng.choice([False, True]))
        item["orientation"] = "역방향" if is_reversed else "정방향"
        item["keywords"] = item["reversed"] if is_reversed else item["upright"]
        result.append(item)
    return result


def tarot_cards_text(cards):
    positions = tarot_spread_positions(len(cards))
    lines = []
    for idx, card in enumerate(cards):
        lines.append(
            f"{idx + 1}. {positions[idx]}: {card['name']} ({card['english']}, {card['orientation']})"
            f" — {card['keywords']}"
        )
    return "\n".join(lines)


def tarot_card_symbol(card):
    """실물형 카드 중앙 일러스트에 사용할 상징을 반환합니다."""
    english = str(card.get("english", "") or "")
    name = str(card.get("name", "") or "")

    if str(card.get("arcana", "")) == "메이저":
        major_symbols = {
            "The Fool": "✧",
            "The Magician": "✦",
            "The High Priestess": "☾",
            "The Empress": "❀",
            "The Emperor": "♜",
            "The Hierophant": "⚜",
            "The Lovers": "♡",
            "The Chariot": "✥",
            "Strength": "♌",
            "The Hermit": "✶",
            "Wheel of Fortune": "⊙",
            "Justice": "⚖",
            "The Hanged Man": "∞",
            "Death": "✢",
            "Temperance": "◐",
            "The Devil": "♑",
            "The Tower": "ϟ",
            "The Star": "★",
            "The Moon": "☾",
            "The Sun": "☀",
            "Judgement": "✺",
            "The World": "◎",
        }
        return major_symbols.get(english, "✦")

    if name.startswith("완드"):
        return "♜"
    if name.startswith("컵"):
        return "♧"
    if name.startswith("소드"):
        return "⚔"
    if name.startswith("펜타클"):
        return "✥"
    return "✦"


def tarot_card_top_label(card):
    """메이저 번호 또는 마이너 계열명을 카드 상단 표기로 사용합니다."""
    card_id = str(card.get("id", "") or "")
    arcana = str(card.get("arcana", "") or "")
    name = str(card.get("name", "") or "")

    if arcana == "메이저" and card_id.startswith("major-"):
        number = card_id.split("-", 1)[1]
        roman = {
            "0": "0", "1": "I", "2": "II", "3": "III", "4": "IV",
            "5": "V", "6": "VI", "7": "VII", "8": "VIII", "9": "IX",
            "10": "X", "11": "XI", "12": "XII", "13": "XIII",
            "14": "XIV", "15": "XV", "16": "XVI", "17": "XVII",
            "18": "XVIII", "19": "XIX", "20": "XX", "21": "XXI",
        }
        return roman.get(number, number)

    if name.startswith("완드"):
        return "WANDS"
    if name.startswith("컵"):
        return "CUPS"
    if name.startswith("소드"):
        return "SWORDS"
    if name.startswith("펜타클"):
        return "PENTACLES"
    return "TAROT"


def tarot_card_visual_html(card, position_label=""):
    """실물 타로 카드 비율과 전통적인 앞면 구성을 흉내 낸 HTML 카드입니다."""
    name = escape(str(card.get("name", "") or "타로 카드"))
    english = escape(str(card.get("english", "") or "Tarot"))
    orientation = escape(str(card.get("orientation", "") or "정방향"))
    arcana = escape(str(card.get("arcana", "") or "타로"))
    symbol = tarot_card_symbol(card)
    top_label = escape(tarot_card_top_label(card))
    reversed_class = " tarot-card-reversed" if orientation == "역방향" else ""
    position_html = (
        f'<div class="tarot-position-label">{escape(str(position_label))}</div>'
        if position_label else ""
    )

    card_html = f"""
    <div class="tarot-card-item">
        {position_html}
        <div class="tarot-card-face{reversed_class}">
            <div class="tarot-card-inner-border"></div>
            <div class="tarot-top-number">{top_label}</div>
            <div class="tarot-top-arcana">{arcana}</div>
            <div class="tarot-illustration">
                <div class="tarot-sky">
                    <span class="tarot-star s1">✦</span>
                    <span class="tarot-star s2">·</span>
                    <span class="tarot-star s3">✧</span>
                    <span class="tarot-celestial">☾</span>
                </div>
                <div class="tarot-symbol-halo"></div>
                <div class="tarot-card-symbol">{symbol}</div>
                <div class="tarot-horizon"></div>
                <div class="tarot-hill hill-left"></div>
                <div class="tarot-hill hill-right"></div>
                <div class="tarot-ground-mark">✦　✧　✦</div>
            </div>
            <div class="tarot-title-plaque">
                <div class="tarot-card-name">{name}</div>
                <div class="tarot-card-english">{english}</div>
            </div>
            <div class="tarot-orientation">{orientation}</div>
        </div>
    </div>
    """
    return "".join(line.strip() for line in card_html.splitlines())


def tarot_cards_visual_html(cards, positions=None):
    positions = positions or [""] * len(cards)
    items = []
    for idx, card in enumerate(cards):
        label = positions[idx] if idx < len(positions) else ""
        items.append(tarot_card_visual_html(card, label))
    return '<div class="tarot-visual-grid">' + "".join(items) + "</div>"

def ask_ai_tarot(
    *,
    api_key,
    model,
    question,
    topic,
    cards,
    include_saju=False,
    saju_context="",
):
    if OpenAI is None:
        raise RuntimeError("openai 패키지가 설치되어 있지 않습니다.")

    client = OpenAI(api_key=api_key)
    card_text = tarot_cards_text(cards)
    question_text = _clip_ai_text(question, 600) or "뽑힌 카드를 바탕으로 지금 살펴볼 점을 알려주세요."

    instructions = """
당신은 한국어로 답하는 '생활 중심 타로 상담 도우미'입니다.
타로 카드는 미래를 확정하거나 초자연적 사실을 증명하는 도구가 아니라,
현재 고민을 다른 각도에서 정리하고 선택지를 살펴보는 상징적 참고자료로만 사용합니다.

반드시 지킬 원칙:
1. 카드가 미래를 확정한다고 말하지 않습니다. '반드시', '운명적으로', '무조건', '곧 생긴다' 같은 단정은 피합니다.
2. 카드의 상징을 사용자의 현실적인 선택, 감정, 준비사항과 연결합니다.
3. 건강·투자·대출·법률처럼 중요한 결정은 타로로 결론내리지 않습니다. 필요한 경우 전문가 확인과 실제 자료 점검을 안내합니다.
4. 관계 질문에서도 상대방의 속마음이나 행동을 사실처럼 단정하지 않습니다.
5. 불안을 키우는 표현보다 확인할 조건, 선택지, 작은 행동을 제시합니다.
5-1. 어려운 카드나 역방향 카드가 나와도 '나쁜 결과'로 몰지 말고, 조절할 수 있는 부분과 회복의 여지, 지금 취할 수 있는 행동을 반드시 함께 설명합니다.
5-2. 희망적인 표현을 쓰되 좋은 결과를 확정하거나 보장하지 않습니다.
6. 사주 정보가 함께 제공되어도 사주와 타로를 '서로 맞다/틀리다'로 판정하지 않고 공통 주제만 참고합니다.
7. 전체 답변은 한국어 650~950자 정도로 간결하게 씁니다.

답변 순서:
**카드가 비추는 핵심** — 질문을 바라볼 핵심 관점 1~2문장
**카드별 해석** — 각 카드의 위치와 상징을 현실적인 말로 설명
**사주와 함께 보면** — 사주 정보가 제공된 경우에만 공통 주제를 짧게 연결
**현실에서 확인할 점** — 실제로 확인할 조건 2~3가지
**지금 해볼 한 걸음** — 오늘 또는 이번 주에 할 수 있는 행동 1가지
""".strip()

    saju_part = saju_context if include_saju and saju_context else "(사주 연결 해석 사용 안 함)"
    user_input = f"""
[질문 분야]
{topic}

[사용자 질문]
{question_text}

[뽑힌 카드]
{card_text}

[사주 참고 요약]
{saju_part}
""".strip()

    response = client.responses.create(
        model=model,
        instructions=instructions,
        input=[{"role": "user", "content": user_input}],
        max_output_tokens=800,
        store=False,
    )
    answer = (response.output_text or "").strip()
    if not answer:
        raise RuntimeError("AI가 빈 타로 답변을 반환했습니다.")
    return answer



